bool AIE2PInstructionSelector ::selectVSHUFFLE_BFP(MachineInstr &I,
                                                   MachineRegisterInfo &MRI) {
  Register DstMant = I.getOperand(0).getReg();
  Register DstExp = I.getOperand(1).getReg();
  Register Src1Mant = I.getOperand(3).getReg();
  Register Src1Exp = I.getOperand(4).getReg();
  Register Src2Mant = I.getOperand(5).getReg();
  Register Src2Exp = I.getOperand(6).getReg();
  Register Mode = I.getOperand(7).getReg();

  unsigned OpCode = TII.getOpCode(I);
  Register Src1Reg = MRI.createVirtualRegister(&AIE2P::mEXmRegClass);
  MachineInstrBuilder RegSeq1 =
      MIB.buildInstr(TargetOpcode::REG_SEQUENCE, {Src1Reg}, {})
          .addReg(Src1Mant)
          .addImm(AIE2P::sub_bfp16_x)
          .addReg(Src1Exp)
          .addImm(AIE2P::sub_bfp16_e);
  Register Src2Reg = MRI.createVirtualRegister(&AIE2P::mEXnRegClass);
  MachineInstrBuilder RegSeq2 =
      MIB.buildInstr(TargetOpcode::REG_SEQUENCE, {Src2Reg}, {})
          .addReg(Src2Mant)
          .addImm(AIE2P::sub_bfp16_x)
          .addReg(Src2Exp)
          .addImm(AIE2P::sub_bfp16_e);
  constrainOperandRegClass(*MF, TRI, MRI, TII, RBI, *RegSeq1,
                           AIE2P::VEC512RegClass, RegSeq1->getOperand(1));
  constrainOperandRegClass(*MF, TRI, MRI, TII, RBI, *RegSeq1,
                           AIE2P::EXPVEC64RegClass, RegSeq1->getOperand(3));
  constrainOperandRegClass(*MF, TRI, MRI, TII, RBI, *RegSeq2,
                           AIE2P::VEC512RegClass, RegSeq2->getOperand(1));
  constrainOperandRegClass(*MF, TRI, MRI, TII, RBI, *RegSeq2,
                           AIE2P::EXPVEC64RegClass, RegSeq2->getOperand(3));

  Register DstReg = MRI.createVirtualRegister(&AIE2P::mEXmRegClass);
  MachineInstrBuilder MI =
      MIB.buildInstr(OpCode, {DstReg}, {Src1Reg, Src2Reg, Mode});

  auto MantCopyMI = MIB.buildInstr(TargetOpcode::COPY, {DstMant}, {})
                        .addReg(DstReg, 0, AIE2P::sub_bfp16_x);
  auto ExpCopyMI = MIB.buildInstr(TargetOpcode::COPY, {DstExp}, {})
                       .addReg(DstReg, 0, AIE2P::sub_bfp16_e);
  constrainOperandRegClass(*MF, TRI, MRI, TII, RBI, *MantCopyMI,
                           AIE2P::VEC512RegClass, MantCopyMI->getOperand(0));

  constrainOperandRegClass(*MF, TRI, MRI, TII, RBI, *ExpCopyMI,
                           AIE2P::EXPVEC64RegClass, ExpCopyMI->getOperand(0));

  I.eraseFromParent();
  return constrainSelectedInstRegOperands(*MI, TII, TRI, RBI);
}

bool AIE2PInstructionSelector::selectVST_FIFO_CONV(MachineInstr &StoreI,
                                                   MachineRegisterInfo &MRI) {
  Register ConvResult = StoreI.getOperand(5).getReg();
  MachineInstr *ConvOp = getDefIgnoringCopiesAndBitcasts(ConvResult, MRI);
  assert(ConvOp && "Expected SSA.");

  if (!canCombineCONVStore(StoreI, *ConvOp) ||
      StoreI.getParent() != ConvOp->getParent() || !MRI.hasOneUse(ConvResult))
    return false;

  const std::optional<APInt> NoImmediate = {};
  std::optional<LoadStoreOpcodes> LSO =
      getCombinedOpcodeCONVStore(StoreI, *ConvOp, NoImmediate);
  assert(LSO && "Unexpected VST.FIFO.CONV combine failure");

  Register PtrOut = StoreI.getOperand(0).getReg();
  Register FifoOut = StoreI.getOperand(1).getReg();
  Register AvailOut = StoreI.getOperand(2).getReg();

  Register PtrIn = StoreI.getOperand(4).getReg();
  Register FifoIn = StoreI.getOperand(7).getReg();
  Register AvailIn = StoreI.getOperand(8).getReg();
  Register SrcReg;

  unsigned CombOpID = cast<GIntrinsic>(*ConvOp).getIntrinsicID();
  if (CombOpID == Intrinsic::aie2p_v64bfp16ebs8_to_v64bfp16ebs16) {
    Register MantIn = ConvOp->getOperand(3).getReg();
    Register ExpIn = ConvOp->getOperand(4).getReg();
    SrcReg = MRI.createVirtualRegister(&AIE2P::mEXaRegClass);
    MIB.buildInstr(TargetOpcode::REG_SEQUENCE, {SrcReg}, {})
        .addReg(MantIn)
        .addImm(AIE2P::sub_bfp16_x)
        .addReg(ExpIn)
        .addImm(AIE2P::sub_bfp16_e);
  } else {
    assert((CombOpID == Intrinsic::aie2p_v64accfloat_to_v64bfp16ebs8 ||
            CombOpID == Intrinsic::aie2p_v64accfloat_to_v64bfp16ebs16) &&
           "Unexpected IntrinsicID in VST.FIFO.CONV combine");
    SrcReg = ConvOp->getOperand(3).getReg();
  }

  auto NewInstr = MIB.buildInstr(LSO->ISelOpcode, {FifoOut, PtrOut, AvailOut},
                                 {FifoIn, SrcReg, PtrIn, AvailIn});
  NewInstr.cloneMemRefs(StoreI);

  makeDeadMI(*ConvOp, MRI);
  StoreI.eraseFromParent();

  return constrainSelectedInstRegOperands(*NewInstr.getInstr(), TII, TRI, RBI);
}

bool AIE2PInstructionSelector::selectVST_FIFO_BFP16(MachineInstr &I,
                                                    MachineRegisterInfo &MRI) {
  // First try to match CONV combine
  if (selectVST_FIFO_CONV(I, MRI))
    return true;

  const auto IntrinsicID = cast<GIntrinsic>(I).getIntrinsicID();
  const unsigned Opcode =
      (IntrinsicID == Intrinsic::aie2p_fifo_st_push_576_bfp16)
          ? AIE2P::VST_PUSH_576
          : AIE2P::VST_PUSH_544;

  const Register PtrOut = I.getOperand(0).getReg();
  const Register FifoOut = I.getOperand(1).getReg();
  const Register AvailOut = I.getOperand(2).getReg();
  const Register PtrIn = I.getOperand(4).getReg();
  const Register MantIn = I.getOperand(5).getReg();
  const Register ExpIn = I.getOperand(6).getReg();
  const Register FifoIn = I.getOperand(7).getReg();
  const Register AvailIn = I.getOperand(8).getReg();

  const Register SrcReg = MRI.createVirtualRegister(&AIE2P::mEXaRegClass);
  MIB.buildInstr(TargetOpcode::REG_SEQUENCE, {SrcReg}, {})
      .addReg(MantIn)
      .addImm(AIE2P::sub_bfp16_x)
      .addReg(ExpIn)
      .addImm(AIE2P::sub_bfp16_e);

  auto MI = MIB.buildInstr(Opcode, {FifoOut, PtrOut, AvailOut},
                           {FifoIn, SrcReg, PtrIn, AvailIn});
  MI.cloneMemRefs(I);
  I.eraseFromParent();
  return constrainSelectedInstRegOperands(*MI, TII, TRI, RBI);
}
namespace llvm {
InstructionSelector *
createAIE2PInstructionSelector(const AIE2PTargetMachine &TM,
                               AIE2PSubtarget &Subtarget,
                               AIE2PRegisterBankInfo &RBI) {
  return new AIE2PInstructionSelector(TM, Subtarget, RBI);
}

} // end namespace llvm
